:- module(m__eu_ai_act_serious_incident_reporting_citations, [citation/2, implements/1, citation_vocabulary/1, referral_row/2]).
:- use_module(library(lists)).
:- use_module(library(iso_ext)).
:- use_module(library(between)).
:- use_module(library(dif)).

implements(Key) :-
    citation(Key, _).

citation(eu_reg_2024_1689_art_3_49, [label - 'Regulation (EU) 2024/1689 Art 3, lead text and point (49), definition of serious incident', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02024R1689-20260727', verbatim - 'serious incident means an incident or malfunctioning of an AI system that directly or indirectly leads to any of the following:']).
citation(eu_reg_2024_1689_art_3_49_a, [label - 'Regulation (EU) 2024/1689 Art 3, point (49)(a), serious incident: death or serious harm to health', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02024R1689-20260727', verbatim - 'the death of a person, or serious harm to a person’s health;']).
citation(eu_reg_2024_1689_art_3_49_b, [label - 'Regulation (EU) 2024/1689 Art 3, point (49)(b), serious incident: disruption of critical infrastructure', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02024R1689-20260727', verbatim - 'a serious and irreversible disruption of the management or operation of critical infrastructure;']).
citation(eu_reg_2024_1689_art_3_49_c, [label - 'Regulation (EU) 2024/1689 Art 3, point (49)(c), serious incident: infringement of fundamental-rights obligations', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02024R1689-20260727', verbatim - 'the infringement of obligations under Union law intended to protect fundamental rights;']).
citation(eu_reg_2024_1689_art_3_49_d, [label - 'Regulation (EU) 2024/1689 Art 3, point (49)(d), serious incident: serious harm to property or the environment', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02024R1689-20260727', verbatim - 'serious harm to property or the environment;']).
citation(eu_reg_2024_1689_art_3_61, [label - 'Regulation (EU) 2024/1689 Art 3, point (61), definition of widespread infringement', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02024R1689-20260727', verbatim - 'widespread infringement means any act or omission contrary to Union law protecting the interest of individuals, which:']).
citation(eu_reg_2024_1689_art_73_1, [label - 'Regulation (EU) 2024/1689 Art 73(1), duty of providers of high-risk AI systems to report serious incidents', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02024R1689-20260727', verbatim - 'Providers of high-risk AI systems placed on the Union market shall report any serious incident to the market surveillance authorities of the Member States where that incident occurred.']).
citation(eu_reg_2024_1689_art_73_2, [label - 'Regulation (EU) 2024/1689 Art 73(2), first subparagraph, report immediately and not later than 15 days after awareness', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02024R1689-20260727', verbatim - 'The report referred to in paragraph 1 shall be made immediately after the provider has established a causal link between the AI system and the serious incident or the reasonable likelihood of such a link, and, in any event, not later than 15 days after the provider or, where applicable, the deployer, becomes aware of the serious incident.']).
citation(eu_reg_2024_1689_art_73_3, [label - 'Regulation (EU) 2024/1689 Art 73(3), widespread infringement or Art 3(49)(b) incident: not later than two days', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02024R1689-20260727', verbatim - 'Notwithstanding paragraph 2 of this Article, in the event of a widespread infringement or a serious incident as defined in Article 3, point (49)(b), the report referred to in paragraph 1 of this Article shall be provided immediately, and not later than two days after the provider or, where applicable, the deployer becomes aware of that incident.']).
citation(eu_reg_2024_1689_art_73_4, [label - 'Regulation (EU) 2024/1689 Art 73(4), death of a person: not later than 10 days', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02024R1689-20260727', verbatim - 'Notwithstanding paragraph 2, in the event of the death of a person, the report shall be provided immediately after the provider or the deployer has established, or as soon as it suspects, a causal relationship between the high-risk AI system and the serious incident, but not later than 10 days after the date on which the provider or, where applicable, the deployer becomes aware of the serious incident.']).
citation(eu_reg_2024_1689_art_73_5, [label - 'Regulation (EU) 2024/1689 Art 73(5), incomplete initial report followed by a complete report', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02024R1689-20260727', verbatim - 'Where necessary to ensure timely reporting, the provider or, where applicable, the deployer, may submit an initial report that is incomplete, followed by a complete report.']).
citation(eu_reg_2024_1689_art_73_6, [label - 'Regulation (EU) 2024/1689 Art 73(6), follow-up investigations, risk assessment, corrective action and cooperation', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02024R1689-20260727', verbatim - 'Following the reporting of a serious incident pursuant to paragraph 1, the provider shall, without delay, perform the necessary investigations in relation to the serious incident and the AI system concerned. This shall include a risk assessment of the incident, and corrective action.']).
citation(eu_reg_2024_1689_art_73_9, [label - 'Regulation (EU) 2024/1689 Art 73(9), Annex III systems of providers with equivalent Union reporting obligations: notification limited to Art 3(49)(c)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02024R1689-20260727', verbatim - 'For high-risk AI systems referred to in Annex III that are placed on the market or put into service by providers that are subject to Union legislative instruments laying down reporting obligations equivalent to those set out in this Regulation, the notification of serious incidents shall be limited to those referred to in Article 3, point (49)(c).']).
citation(eu_reg_2024_1689_art_73_10, [label - 'Regulation (EU) 2024/1689 Art 73(10), medical devices: notification limited to Art 3(49)(c), made to the national competent authority', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02024R1689-20260727', verbatim - 'For high-risk AI systems which are safety components of devices, or are themselves devices, covered by Regulations (EU) 2017/745 and (EU) 2017/746, the notification of serious incidents shall be limited to those referred to in Article 3, point (49)(c) of this Regulation, and shall be made to the national competent authority chosen for that purpose by the Member States where the incident occurred.']).
citation(eu_reg_2024_1689_art_111_2, [label - 'Regulation (EU) 2024/1689 Art 111(2), high-risk AI systems placed on the market or put into service before the date of application of Chapter III', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02024R1689-20260727', verbatim - 'only if, as from that date, those systems are subject to significant changes in their designs. In any case, the providers and deployers of high-risk AI systems intended to be used by public authorities shall take the necessary steps to comply with the requirements and obligations laid down in this Regulation by 2 August 2030.']).
citation(eu_reg_2024_1689_art_113, [label - 'Regulation (EU) 2024/1689 Art 113, second paragraph, general date of application', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02024R1689-20260727', verbatim - 'It shall apply from 2 August 2026.']).
citation(eu_reg_2024_1689_art_113_c, [label - 'Regulation (EU) 2024/1689 Art 113, third paragraph, point (c), date of application of Chapter III, Sections 1 to 3', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02024R1689-20260727', verbatim - 'Chapter III, Sections 1, 2, and 3, with the exception of Article 6(5), shall apply from:']).
citation(eu_reg_2024_1689_art_113_c_i, [label - 'Regulation (EU) 2024/1689 Art 113, third paragraph, point (c)(i), 2 December 2027 for Art 6(2) and Annex III systems', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02024R1689-20260727', verbatim - '2 December 2027 as regards AI systems classified as high-risk pursuant to Article 6(2) and Annex III; and']).
citation(eu_reg_2024_1689_art_113_c_ii, [label - 'Regulation (EU) 2024/1689 Art 113, third paragraph, point (c)(ii), 2 August 2028 for Art 6(1) and Annex I systems', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02024R1689-20260727', verbatim - '2 August 2028 as regards AI systems classified as high-risk pursuant to Article 6(1) and Annex I;']).

citation_vocabulary([eu_reg_2024_1689_art_3_49, eu_reg_2024_1689_art_3_49_c, eu_reg_2024_1689_art_3_61, eu_reg_2024_1689_art_73_1, eu_reg_2024_1689_art_73_2, eu_reg_2024_1689_art_73_3, eu_reg_2024_1689_art_73_4, eu_reg_2024_1689_art_73_6, eu_reg_2024_1689_art_73_9, eu_reg_2024_1689_art_73_10, eu_reg_2024_1689_art_111_2, eu_reg_2024_1689_art_113_c, eu_reg_2024_1689_art_113_c_i, eu_reg_2024_1689_art_113_c_ii]).

referral_row(significant_change_in_design_since_that_date, cite(eu_reg_2024_1689_art_111_2)).
referral_row(provider_subject_to_equivalent_union_reporting_obligations, cite(eu_reg_2024_1689_art_73_9)).
referral_row(widespread_infringement, cite(eu_reg_2024_1689_art_3_61)).
referral_row(report_made_immediately, cite(eu_reg_2024_1689_art_73_2)).
